dir_list = mssparkutils.fs.ls(tmp_path)
file_list = []
prefix = 'recipient_id='
dict_recipients_filenames = {}

for path in dir_list:
    current_path = mssparkutils.fs.ls(path.path)[0].path
    if current_path.endswith(".csv"):
        recipient_id = path.path.split("/")[-1].replace(prefix, "")
        dict_recipients_filenames[recipient_id] = current_path

new_prefix = f"{container_path}/invoices/"
new_filename = str(reference_year) + "-q" + str(reference_quarter) + "-DetailedReport.csv"

for recipient in dict_recipients_filenames:
    new_path = new_prefix + recipient + "/" + new_filename
    try:
        mssparkutils.fs.mv(dict_recipients_filenames[recipient], new_path, True)
    except Py4JJavaError:
        mssparkutils.fs.rm(new_path)
        mssparkutils.fs.mv(dict_recipients_filenames[recipient], new_path, True)

